+/// AV1 in MP4's container bytes, decided in the core (spec §11 CX-12 (4)): the
+/// `av1C` record from SVT-AV1's sequence header, each packet's temporal
+/// delimiters stripped, and the written file's `ftyp` branded `av01`.
+enum ReelAV1 {
+    struct Color: Decodable {
+        let primaries, transfer, matrix: Int
+        let fullRange: Bool
+    }
+
+    /// `rc_av1_config`'s answer; `record` is the `av1C` atom's body.
+    struct Config: Decodable {
+        let record: Data
+        let seqProfile, seqLevelIdx, seqTier, bitDepth: Int
+        let monochrome: Bool
+        let color: Color
+
+        private enum CodingKeys: String, CodingKey {
+            case av1cHex, seqProfile, seqLevelIdx, seqTier, bitDepth, monochrome, color
+        }
+
+        init(from decoder: any Decoder) throws {
+            let c = try decoder.container(keyedBy: CodingKeys.self)
+            let hex = Array(try c.decode(String.self, forKey: .av1cHex).utf8)
+            let bytes = stride(from: 0, to: hex.count - 1, by: 2).compactMap {
+                UInt8(String(decoding: hex[$0...$0 + 1], as: UTF8.self), radix: 16)
+            }
+            guard bytes.count * 2 == hex.count else {
+                throw DecodingError.dataCorruptedError(
+                    forKey: .av1cHex, in: c, debugDescription: "not hex")
+            }
+            record = Data(bytes)
+            seqProfile = try c.decode(Int.self, forKey: .seqProfile)
+            seqLevelIdx = try c.decode(Int.self, forKey: .seqLevelIdx)
+            seqTier = try c.decode(Int.self, forKey: .seqTier)
+            bitDepth = try c.decode(Int.self, forKey: .bitDepth)
+            monochrome = try c.decode(Bool.self, forKey: .monochrome)
+            color = try c.decode(Color.self, forKey: .color)
+        }
+    }
+
+    /// The record for the first sequence header OBU in `sequenceHeader`; throws
+    /// the core's sentence when there is none or it ends early.
+    static func config(sequenceHeader: Data) throws -> Config {
+        var err: UnsafeMutablePointer<CChar>? = nil
+        let raw: UnsafeMutablePointer<CChar>? = sequenceHeader.withUnsafeBytes {
+            rc_av1_config($0.bindMemory(to: UInt8.self).baseAddress, $0.count, &err)
+        }
+        guard let text = takeString(raw) else {
+            throw ReelCoreError(
+                message: takeErrorMessage(err, fallback: "the av1C record could not be built"))
+        }
+        guard let config = ReelJSON.decode(Config.self, from: text) else {
+            throw ReelCoreError(message: "the core's av1C answer could not be read: \(text)")
+        }
