 25	    let formatDescription: CMVideoFormatDescription
 26	
 27	    private var encoder: SVTAV1Encoder?
 28	    private let converter: ExportI420Converter
 29	    private let encodeQueue = DispatchQueue(
 30	        label: "com.kgalligan.framejob.export.encode", qos: .userInitiated)
 31	    private let range: CMTimeRange
 32	    private let frameDuration: CMTime
 33	    private let slots = DispatchSemaphore(value: 3)
 34	
 35	    // The encode queue's own state.
 36	    private var times: [Int64: CMTime] = [:]
 37	    private var lastTime = CMTime.negativeInfinity
 38	    private var encoderFailed = false
 39	    private var finished = false
 40	
 41	    init(settings: ExportSettings, canvas: CGSize, range: CMTimeRange) throws {
 42	        let frame = ExportWriter.encodedSize(settings)
 43	        let speed = settings.encoderSpeed ?? .balanced
 44	        let rate = settings.videoBitrate.map { max(1, $0) }
 45	            ?? ExportWriter.defaultVideoBitrate(settings, bitsPerPixel: 0.07)
 46	        let encoder = try SVTAV1Encoder(
 47	            width: frame.width, height: frame.height, fps: settings.fps, bitsPerSecond: rate,
 48	            speed: speed)
 49	        let config: ReelAV1.Config
 50	        do {
 51	            config = try ReelAV1.config(sequenceHeader: encoder.sequenceHeader)
 52	        } catch {
 53	            throw Exporter.ExportError.failed(
 54	                "SVT-AV1's sequence header could not be read: \(error.localizedDescription)")
 55	        }
 56	        formatDescription = try ExportAV1Track.formatDescription(
 57	            width: frame.width, height: frame.height, config: config)
 58	        converter = try ExportI420Converter(
 59	            width: frame.width, height: frame.height, canvas: canvas,
 60	            fills: ExportWriter.fillsTheBox(settings, canvas: canvas), pool: 3)
 61	        self.encoder = encoder
 62	        self.range = range
 63	        self.frameDuration = CompositionBuilder.frameDuration(settings.fps)
 64	    }
 65	
 66	    @available(*, unavailable) required init?(coder: NSCoder) {
 67	        fatalError("ExportEncodePump does not support NSCoder")
 68	    }
 69	
 70	    /// Reads `output` to its end on `queue` and encodes it into `input`; `group` is left once
 71	    /// the input is finished. `readFailure` answers the reader's error when the read failed;
 72	    /// `fail` records the first failure; `advance` is each submitted frame's file time.
 73	    func run(
 74	        input: AVAssetWriterInput, output: AVAssetReaderOutput, on queue: DispatchQueue,
 75	        group: DispatchGroup, isStopping: @escaping () -> Bool,
 76	        readFailure: @escaping () -> (any Error)?, fail: @escaping (any Error) -> Void,
 77	        advance: @escaping (CMTime) -> Void
 78	    ) {
 79	        group.enter()
 80	        let finish: (Bool) -> Void = { [self] clean in
 81	            encodeQueue.async {
 82	                self.finish(
 83	                    clean: clean, input: input, group: group, isStopping: isStopping, fail: fail)
 84	            }
 85	        }
 86	        queue.async { [self] in
 87	            var index: Int64 = 0
 88	            while true {
 89	                guard !isStopping() else { return finish(false) }
 90	                guard let sample = output.copyNextSampleBuffer() else {
 91	                    // Dry: the range is read, or the read failed — never a branded, done
 92	                    // file after a failed read.
 93	                    if let error = readFailure() {
 94	                        fail(error)
 95	                        return finish(false)
 96	                    }
 97	                    return finish(true)
 98	                }
 99	                let time = CMSampleBufferGetPresentationTimeStamp(sample) - range.start
100	                guard time.isNumeric, time >= .zero else { continue }
101	                slots.wait()
102	                guard let pixels = CMSampleBufferGetImageBuffer(sample),
103	                    let frame = converter.convert(pixels)
104	                else {
105	                    slots.signal()
106	                    fail(Exporter.ExportError.failed(
107	                        "A frame could not be prepared for the encoder."))
108	                    return finish(false)
109	                }
110	                let at = index
111	                index += 1
112	                encodeQueue.async {
113	                    self.encode(
114	                        frame, index: at, time: time, input: input, isStopping: isStopping,
115	                        fail: fail)
116	                }
117	                advance(time)
118	            }
119	        }
120	    }
121	
122	    /// The encoder's teardown, on the encode queue, once every input is finished.
123	    func close() {
124	        encodeQueue.async { [self] in encoder = nil }
125	    }
126	
127	    // MARK: - The encode queue
128	
129	    private func encode(
130	        _ frame: I420Frame, index: Int64, time: CMTime, input: AVAssetWriterInput,
131	        isStopping: () -> Bool, fail: (any Error) -> Void
132	    ) {
133	        defer {
134	            converter.recycle(frame)
135	            slots.signal()
136	        }
137	        guard !finished, !encoderFailed, !isStopping(), let encoder else { return }
138	        do {
139	            try encoder.send(frame, index: index)
140	            times[index] = time
141	            while let packet = try encoder.nextPacket(wait: false) {
142	                guard write(packet, input: input, isStopping: isStopping, fail: fail) else {
143	                    return
144	                }
145	            }
146	        } catch {
147	            encoderFailed = true
148	            fail(error)
149	        }
150	    }
151	
152	    /// One packet into the file: false once the export cannot go on.
153	    private func write(
154	        _ packet: SVTAV1Encoder.Packet, input: AVAssetWriterInput, isStopping: () -> Bool,
155	        fail: (any Error) -> Void
156	    ) -> Bool {
157	        guard !packet.data.isEmpty else { return true }
158	        var data = packet.data
159	        guard ReelAV1.stripTemporalDelimiters(&data) else {
160	            fail(Exporter.ExportError.failed("SVT-AV1 wrote a packet the core could not read."))
161	            return false
162	        }
163	        guard let time = times.removeValue(forKey: packet.pts), time > lastTime else {
164	            fail(Exporter.ExportError.failed("SVT-AV1 wrote a frame out of order."))
165	            return false
166	        }
167	        lastTime = time
168	        guard let sample = ExportAV1Track.sample(
169	            data, at: time, duration: frameDuration, sync: packet.isKey,
170	            format: formatDescription)
171	        else {
172	            fail(Exporter.ExportError.failed("An AV1 packet could not be made a sample."))
173	            return false
174	        }
175	        while !input.isReadyForMoreMediaData {
176	            guard !isStopping() else { return false }
177	            usleep(1000)
178	        }
179	        guard input.append(sample) else {
180	            fail(Exporter.ExportError.failed("The file could not be written."))
181	            return false
182	        }
183	        return true
184	    }
185	
186	    /// The one exit: the end of stream and the drain as `clean` and the encoder allow, then
187	    /// the input finished and the group left, exactly once.
188	    private func finish(
189	        clean: Bool, input: AVAssetWriterInput, group: DispatchGroup, isStopping: () -> Bool,
190	        fail: (any Error) -> Void
191	    ) {
192	        guard !finished else { return }
193	        finished = true
194	        defer {
195	            input.markAsFinished()
196	            group.leave()
197	        }
198	        guard !encoderFailed, let encoder else { return }
199	        do {
200	            try encoder.sendEndOfStream()
201	            var writing = clean && !isStopping()
202	            while let packet = try encoder.nextPacket(wait: true) {
203	                if writing {
204	                    writing = write(packet, input: input, isStopping: isStopping, fail: fail)
205	                }
206	                if packet.isLast { break }
207	            }
208	        } catch {
209	            encoderFailed = true
210	            if clean { fail(error) }
211	        }
212	    }
213	}
  1	import Foundation
  2	
  3	/// SVT-AV1 v4.2.0, the `av1` row's encoder (spec §11 CX-2, CX-4, CX-12): one handle per
  4	/// export, configured once, fed BT.709 video-range I420 pictures and drained of packets.
  5	///
  6	/// **Owned by one serial queue.** `ExportEncodePump`'s encode queue makes every call after
  7	/// `init` — `send`, `sendEndOfStream`, `nextPacket` and the `deinit` — so the handle is
  8	/// never touched from two threads; SVT runs its own worker threads behind it.
  9	///
 10	/// **The configuration** (CX-12 (2), (3); CX-9): the sheet's speed as SVT's preset (8, 6 or
 11	/// 4), single-pass VBR at the settings' rate or HEVC's 0.07 bits per pixel per frame, a
 12	/// closed GOP (`SVT_AV1_KF_REFRESH`) with a keyframe at least every 2 s, 8-bit 4:2:0, and
 13	/// BT.709 primaries, transfer and matrix in video range written into the sequence header.
 14	final class SVTAV1Encoder {
 15	    /// One packet as SVT answered it: its bytes (temporal delimiters still in), the `pts` the
 16	    /// picture was sent with, whether it is a key picture, and whether it is the last.
 17	    struct Packet {
 18	        let data: Data
 19	        let pts: Int64
 20	        let isKey: Bool
 21	        let isLast: Bool
 22	    }
 23	
 24	    /// The sequence header OBU (`svt_av1_enc_stream_header`), the `av1C` record's source.
 25	    let sequenceHeader: Data
 26	
 27	    private var handle: UnsafeMutablePointer<EbComponentType>?
 28	    /// Set after the first failed call: nothing more is asked of the handle but its teardown.
 29	    private var broken = false
 30	
 31	    init(width: Int, height: Int, fps: Fps, bitsPerSecond: Int, speed: EncoderSpeed) throws {
 32	        _ = Self.installLogCallback
 33	        var config = EbSvtAv1EncConfiguration()
 34	        var opened: UnsafeMutablePointer<EbComponentType>?
 35	        try Self.check(svt_av1_enc_init_handle(&opened, &config), "svt_av1_enc_init_handle")
 36	        guard let opened else {
 37	            throw Exporter.ExportError.failed("SVT-AV1 could not start: no handle was made.")
 38	        }
 39	        config.enc_mode = speed.svtPreset
 40	        config.source_width = UInt32(clamping: width)
 41	        config.source_height = UInt32(clamping: height)
 42	        config.frame_rate_numerator = UInt32(clamping: fps.num)
 43	        config.frame_rate_denominator = UInt32(clamping: fps.den)
 44	        config.encoder_bit_depth = 8
 45	        config.encoder_color_format = EB_YUV420
 46	        config.rate_control_mode = UInt8(SVT_AV1_RC_MODE_VBR.rawValue)
 47	        config.target_bit_rate = UInt32(clamping: max(1, bitsPerSecond))
 48	        // Closed GOP, and a keyframe at least every 2 s: the period is ⌊2·fps⌋ frames.
 49	        config.intra_refresh_type = SVT_AV1_KF_REFRESH
 50	        let perSecond = fps.den > 0 ? Double(fps.num) / Double(fps.den) : 30
 51	        config.intra_period_length = Int32(max(1, (2 * perSecond).rounded(.down))) - 1
 52	        config.color_primaries = EB_CICP_CP_BT_709
 53	        config.transfer_characteristics = EB_CICP_TC_BT_709
 54	        config.matrix_coefficients = EB_CICP_MC_BT_709
 55	        config.color_range = EB_CR_STUDIO_RANGE
 56	        do {
 57	            sequenceHeader = try Self.start(opened, &config)
 58	        } catch {
 59	            _ = svt_av1_enc_deinit(opened)
 60	            _ = svt_av1_enc_deinit_handle(opened)
 61	            throw error
 62	        }
 63	        handle = opened
 64	    }
 65	
 66	    /// Configures and starts the handle, answering its sequence header.
 67	    private static func start(
 68	        _ handle: UnsafeMutablePointer<EbComponentType>, _ config: inout EbSvtAv1EncConfiguration
 69	    ) throws -> Data {
 70	        try check(svt_av1_enc_set_parameter(handle, &config), "svt_av1_enc_set_parameter")
 71	        try check(svt_av1_enc_init(handle), "svt_av1_enc_init")
 72	        var header: UnsafeMutablePointer<EbBufferHeaderType>?
 73	        try check(svt_av1_enc_stream_header(handle, &header), "svt_av1_enc_stream_header")
 74	        guard let header, let bytes = header.pointee.p_buffer else {
 75	            throw Exporter.ExportError.failed("SVT-AV1 could not start: it wrote no stream header.")
 76	        }
 77	        defer { _ = svt_av1_enc_stream_header_release(header) }
 78	        return Data(bytes: bytes, count: Int(header.pointee.n_filled_len))
 79	    }
 80	
 81	    @available(*, unavailable) required init?(coder: NSCoder) {
 82	        fatalError("SVTAV1Encoder does not support NSCoder")
 83	    }
 84	
 85	    deinit {
 86	        guard let handle else { return }
 87	        _ = svt_av1_enc_deinit(handle)
 88	        _ = svt_av1_enc_deinit_handle(handle)
 89	    }
 90	
 91	    /// Sends one picture; SVT copies its planes, so `frame` may be reused once this returns.
 92	    func send(_ frame: I420Frame, index: Int64) throws {
 93	        guard let handle, !broken else { throw Self.stopped }
 94	        let base = frame.buffer.contents().assumingMemoryBound(to: UInt8.self)
 95	        var planes = EbSvtIOFormat(
 96	            luma: base, cb: base + frame.cbOffset, cr: base + frame.crOffset,
 97	            y_stride: UInt32(frame.lumaStride), cr_stride: UInt32(frame.chromaStride),
 98	            cb_stride: UInt32(frame.chromaStride))
 99	        try withUnsafeMutablePointer(to: &planes) { io in
100	            var picture = EbBufferHeaderType()
101	            picture.size = UInt32(MemoryLayout<EbBufferHeaderType>.size)
102	            picture.p_buffer = UnsafeMutableRawPointer(io).assumingMemoryBound(to: UInt8.self)
103	            let chroma = frame.chromaStride * ((frame.height + 1) / 2)
104	            picture.n_filled_len = UInt32(frame.lumaStride * frame.height + 2 * chroma)
105	            picture.n_alloc_len = picture.n_filled_len
106	            picture.pts = index
107	            picture.pic_type = EB_AV1_INVALID_PICTURE
108	            try record(svt_av1_enc_send_picture(handle, &picture), "svt_av1_enc_send_picture")
109	        }
110	    }
111	
112	    /// Tells SVT no picture follows, so `nextPacket(wait: true)` drains to the last packet.
113	    func sendEndOfStream() throws {
114	        guard let handle, !broken else { throw Self.stopped }
115	        var end = EbBufferHeaderType()
116	        end.size = UInt32(MemoryLayout<EbBufferHeaderType>.size)
117	        end.flags = UInt32(EB_BUFFERFLAG_EOS)
118	        end.pic_type = EB_AV1_INVALID_PICTURE
119	        try record(svt_av1_enc_send_picture(handle, &end), "svt_av1_enc_send_picture")
120	    }
121	
122	    /// The next packet: nil when none is ready (`wait` false); `wait` true blocks until one
123	    /// is, which is only asked after `sendEndOfStream`.
124	    func nextPacket(wait: Bool) throws -> Packet? {
125	        guard let handle, !broken else { throw Self.stopped }
126	        var out: UnsafeMutablePointer<EbBufferHeaderType>?
127	        let answer = svt_av1_enc_get_packet(handle, &out, wait ? 1 : 0)
128	        if answer == EB_NoErrorEmptyQueue { return nil }
129	        try record(answer, "svt_av1_enc_get_packet")
130	        guard let header = out?.pointee else { return nil }
131	        defer { svt_av1_enc_release_out_buffer(&out) }
132	        let length = Int(header.n_filled_len)
133	        let data = header.p_buffer.map { Data(bytes: $0, count: length) } ?? Data()
134	        return Packet(
135	            data: data, pts: header.pts, isKey: header.pic_type == EB_AV1_KEY_PICTURE,
136	            isLast: header.flags & UInt32(EB_BUFFERFLAG_EOS) != 0)
137	    }
138	
139	    // MARK: - Errors and the log
140	
141	    private static let stopped = Exporter.ExportError.failed(
142	        "SVT-AV1 stopped after an earlier error.")
143	
144	    private func record(_ answer: EbErrorType, _ step: String) throws {
145	        guard answer != EB_ErrorNone else { return }
146	        broken = true
147	        throw Exporter.ExportError.failed("SVT-AV1 failed: \(step) answered \(Self.hex(answer)).")
148	    }
149	
150	    private static func check(_ answer: EbErrorType, _ step: String) throws {
151	        guard answer != EB_ErrorNone else { return }
152	        throw Exporter.ExportError.failed(
153	            "SVT-AV1 could not start: \(step) answered \(hex(answer)).")
154	    }
155	
156	    private static func hex(_ answer: EbErrorType) -> String {
157	        "0x" + String(UInt32(bitPattern: answer.rawValue), radix: 16)
158	    }
159	
160	    /// SVT's log through its callback (spec §11 CX-12 (6)), installed once per process before
161	    /// the first `svt_av1_enc_init_handle`, which finalises the library's logging: info and
162	    /// debug dropped, warnings and errors as `SVT-AV1: …` lines in the system log.
163	    private static let installLogCallback: Void = {
164	        svt_av1_set_log_callback({ _, level, _, format, arguments in
165	            guard level.rawValue >= 0, level.rawValue <= SVT_AV1_LOG_WARN.rawValue, let format,
166	                let arguments
167	            else { return }
168	            var text = [CChar](repeating: 0, count: 1024)
169	            _ = vsnprintf(&text, text.count, format, arguments)
170	            let line = String(cString: text).trimmingCharacters(in: .whitespacesAndNewlines)
171	            NSLog("SVT-AV1: %@", line)
172	        }, nil)
173	    }()
174	}

