  1	//! AV1 in MP4's container bytes (spec §11 CX-12 (4); AV1-ISOBMFF §2): the
  2	//! `av1C` record built from an encoder's sequence header OBU, the temporal
  3	//! delimiters stripped from each sample, and the `av01` brand in the
  4	//! written file's `ftyp`. CX-6's precedent puts container bytes in the
  5	//! core: each is a decision about bytes the encoder handed over, read and
  6	//! rewritten as bytes, and none touches a sample of picture.
  7	//!
  8	//! The encoder is the app's (CX-4); `ffi_av1.rs` exports the three readers
  9	//! here as `rc_av1_*`.
 10	//!
 11	//! **The sequence header is parsed, not assumed.** The `av1C` record's
 12	//! second and third bytes restate the profile, operating point 0's level and
 13	//! tier, and the colour config's depth, monochrome flag, subsampling and
 14	//! chroma position (AV1-ISOBMFF §2.3.3). Every field before `color_config`
 15	//! is walked as AV1 §5.5 writes it — timing info, the decoder model, every
 16	//! operating point, the frame-id lengths, the tool flags, the order hint,
 17	//! the screen-content choices — so an encoder that turns one on moves the
 18	//! read with it rather than past it.
 19	
 20	use serde::Serialize;
 21	
 22	use crate::hdr10::leb128;
 23	
 24	/// The OBU types this file names (AV1 §6.2.2).
 25	const OBU_SEQUENCE_HEADER: u8 = 1;
 26	const OBU_TEMPORAL_DELIMITER: u8 = 2;
 27	/// An OBU header's `obu_extension_flag` and `obu_has_size_field` bits.
 28	const OBU_EXTENSION_BIT: u8 = 0x04;
 29	const OBU_HAS_SIZE_BIT: u8 = 0x02;
 30	/// The record's first byte: its marker bit and version 1.
 31	const AV1C_MARKER_VERSION: u8 = 0x81;
 32	/// `color_config`'s values for "the header describes no colour" (AV1 §6.4.2).
 33	const UNSPECIFIED: u8 = 2;
 34	
 35	/// The colour a sequence header describes.
 36	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
 37	pub struct Av1Color {
 38	    pub primaries: u8,
 39	    pub transfer: u8,
 40	    pub matrix: u8,
 41	    pub full_range: bool,
 42	}
 43	
 44	/// An `av1C` record and the fields it was built from.
 45	#[derive(Debug, Clone, PartialEq, Eq)]
 46	pub struct Av1Config {
 47	    pub record: Vec<u8>,
 48	    pub seq_profile: u8,
 49	    pub seq_level_idx: u8,
 50	    pub seq_tier: u8,
 51	    pub bit_depth: u8,
 52	    pub monochrome: bool,
 53	    pub color: Av1Color,
 54	}
 55	
 56	/// One OBU's place in a run: where it starts, its header's length (the
 57	/// header byte, the extension byte, the size field), its type and where it
 58	/// ends.
 59	struct Obu {
 60	    start: usize,
 61	    header: usize,
 62	    kind: u8,
 63	    end: usize,
 64	}
 65	
 66	/// The OBU at `start` of `bytes`: `None` when its size field is cut short
 67	/// or its payload runs past the end. One without a size field runs to the
 68	/// end (AV1 §5.3.1).
 69	fn obu_at(bytes: &[u8], start: usize) -> Option<Obu> {
 70	    let first = *bytes.get(start)?;
 71	    let mut header = 1 + usize::from(first & OBU_EXTENSION_BIT != 0);
 72	    if start + header > bytes.len() {
 73	        return None;
 74	    }
 75	    let end = if first & OBU_HAS_SIZE_BIT != 0 {
 76	        let (size, used) = leb128(&bytes[start + header..])?;
 77	        header += used;
 78	        let size = usize::try_from(size).ok()?;
 79	        (start + header).checked_add(size)?
 80	    } else {
 81	        bytes.len()
 82	    };
 83	    if end > bytes.len() {
 84	        return None;
 85	    }
 86	    Some(Obu {
 87	        start,
 88	        header,
 89	        kind: (first >> 3) & 0x0f,
 90	        end,
 91	    })
 92	}
 93	
 94	/// An unsigned leb128, the shortest spelling of `value`.
 95	fn leb128_bytes(mut value: usize) -> Vec<u8> {
 96	    let mut out = Vec::new();
 97	    loop {
 98	        let byte = (value & 0x7f) as u8;
 99	        value >>= 7;
100	        if value == 0 {
101	            out.push(byte);
102	            return out;
103	        }
104	        out.push(byte | 0x80);
105	    }
106	}
107	
108	/// A big-endian bit reader over a sequence header's payload, naming the
109	/// field it was reading when the bytes ran out.
110	struct Bits<'a> {
111	    bytes: &'a [u8],
112	    at: usize,
113	}
114	
115	impl Bits<'_> {
116	    fn f(&mut self, n: u32, field: &str) -> Result<u64, String> {
117	        let mut value = 0u64;
118	        for _ in 0..n {
119	            let Some(byte) = self.bytes.get(self.at / 8) else {
120	                return Err(format!(
121	                    "the sequence header ends at bit {}, inside {field}",
122	                    self.at
123	                ));
124	            };
125	            value = (value << 1) | u64::from((byte >> (7 - self.at % 8)) & 1);
126	            self.at += 1;
127	        }
128	        Ok(value)
129	    }
130	
131	    /// One-bit fields read only to be passed over, named in order.
132	    fn flags(&mut self, fields: &str) -> Result<(), String> {
133	        for field in fields.split(' ') {
134	            self.f(1, field)?;
135	        }
136	        Ok(())
137	    }
138	
139	    fn flag(&mut self, field: &str) -> Result<bool, String> {
140	        Ok(self.f(1, field)? == 1)
141	    }
142	
143	    fn byte(&mut self, n: u32, field: &str) -> Result<u8, String> {
144	        Ok(self.f(n, field)? as u8)
145	    }
146	
147	    /// AV1 §4.10.3: leading zeros, then that many bits; a run of 32 or more
148	    /// zeros is the maximum value, and reading past the end is an error, so
149	    /// a payload of zeros cannot loop.
150	    fn uvlc(&mut self, field: &str) -> Result<(), String> {
151	        let mut zeros = 0u32;
152	        while !self.flag(field)? {
153	            zeros += 1;
154	        }
155	        if zeros < 32 {
156	            self.f(zeros, field)?;
157	        }
158	        Ok(())
159	    }
160	}
161	
162	/// AV1 §5.5.1 through `color_config` (§5.5.2): the config with the
163	/// record's four bytes, the OBU still to follow.
164	fn parse_sequence_header(payload: &[u8]) -> Result<Av1Config, String> {
165	    let mut b = Bits {
166	        bytes: payload,
167	        at: 0,
168	    };
169	    let profile = b.byte(3, "seq_profile")?;
170	    b.flag("still_picture")?;
171	    let reduced = b.flag("reduced_still_picture_header")?;
172	    let (level, tier);
173	    if reduced {
174	        level = b.byte(5, "seq_level_idx[0]")?;
175	        tier = 0;
176	    } else {
177	        let mut decoder_model = false;
178	        let mut buffer_delay_bits = 0;
179	        if b.flag("timing_info_present_flag")? {
180	            b.f(32, "num_units_in_display_tick")?;
181	            b.f(32, "time_scale")?;
182	            if b.flag("equal_picture_interval")? {
183	                b.uvlc("num_ticks_per_picture_minus_1")?;
184	            }
185	            decoder_model = b.flag("decoder_model_info_present_flag")?;
186	            if decoder_model {
187	                buffer_delay_bits = b.f(5, "buffer_delay_length_minus_1")? as u32 + 1;
188	                b.f(32, "num_units_in_decoding_tick")?;
189	                b.f(5, "buffer_removal_time_length_minus_1")?;
190	                b.f(5, "frame_presentation_time_length_minus_1")?;
191	            }
192	        }
193	        let display_delay = b.flag("initial_display_delay_present_flag")?;
194	        let points = b.f(5, "operating_points_cnt_minus_1")? + 1;
195	        let mut first = None;
196	        for _ in 0..points {
197	            b.f(12, "operating_point_idc")?;
198	            let idx = b.byte(5, "seq_level_idx")?;
199	            let point_tier = if idx > 7 { b.byte(1, "seq_tier")? } else { 0 };
200	            first.get_or_insert((idx, point_tier));
201	            if decoder_model && b.flag("decoder_model_present_for_this_op")? {
202	                b.f(buffer_delay_bits, "decoder_buffer_delay")?;
203	                b.f(buffer_delay_bits, "encoder_buffer_delay")?;
204	                b.flag("low_delay_mode_flag")?;
205	            }
206	            if display_delay && b.flag("initial_display_delay_present_for_this_op")? {
207	                b.f(4, "initial_display_delay_minus_1")?;
208	            }
209	        }
210	        (level, tier) = first.unwrap_or((0, 0));
211	    }
212	    let width_bits = b.f(4, "frame_width_bits_minus_1")? as u32 + 1;
213	    let height_bits = b.f(4, "frame_height_bits_minus_1")? as u32 + 1;
214	    b.f(width_bits, "max_frame_width_minus_1")?;
215	    b.f(height_bits, "max_frame_height_minus_1")?;
216	    if !reduced && b.flag("frame_id_numbers_present_flag")? {
217	        b.f(4, "delta_frame_id_length_minus_2")?;
218	        b.f(3, "additional_frame_id_length_minus_1")?;
219	    }
220	    b.flags("use_128x128_superblock enable_filter_intra enable_intra_edge_filter")?;
221	    if !reduced {
