244	/// AV1 §5.5.2, and the record's fixed bytes (AV1-ISOBMFF §2.3.3).
245	fn color_config(b: &mut Bits, profile: u8, level: u8, tier: u8) -> Result<Av1Config, String> {
246	    let high_bitdepth = b.flag("high_bitdepth")?;
247	    let twelve_bit = profile == 2 && high_bitdepth && b.flag("twelve_bit")?;
248	    let monochrome = profile != 1 && b.flag("mono_chrome")?;
249	    let color_description = b.flag("color_description_present_flag")?;
250	    let (primaries, transfer, matrix) = if color_description {
251	        (
252	            b.byte(8, "color_primaries")?,
253	            b.byte(8, "transfer_characteristics")?,
254	            b.byte(8, "matrix_coefficients")?,
255	        )
256	    } else {
257	        (UNSPECIFIED, UNSPECIFIED, UNSPECIFIED)
258	    };
259	    let mut chroma_position = 0;
260	    let (full_range, subsampling);
261	    if monochrome {
262	        full_range = b.flag("color_range")?;
263	        subsampling = (true, true);
264	    } else if (primaries, transfer, matrix) == (1, 13, 0) {
265	        // BT.709 primaries, sRGB transfer, identity matrix: 4:4:4 full range.
266	        full_range = true;
267	        subsampling = (false, false);
268	    } else {
269	        full_range = b.flag("color_range")?;
270	        subsampling = match profile {
271	            0 => (true, true),
272	            1 => (false, false),
273	            _ if twelve_bit => {
274	                let x = b.flag("subsampling_x")?;
275	                (x, x && b.flag("subsampling_y")?)
276	            }
277	            _ => (true, false),
278	        };
279	        if subsampling == (true, true) {
280	            chroma_position = b.byte(2, "chroma_sample_position")?;
281	        }
282	    }
283	    if !monochrome {
284	        b.flag("separate_uv_delta_q")?;
285	    }
286	    let bit = |on: bool, shift: u8| u8::from(on) << shift;
287	    let flags = (tier << 7)
288	        | bit(high_bitdepth, 6)
289	        | bit(twelve_bit, 5)
290	        | bit(monochrome, 4)
291	        | bit(subsampling.0, 3)
292	        | bit(subsampling.1, 2)
293	        | (chroma_position & 0x03);
294	    let color = Av1Color {
295	        primaries,
296	        transfer,
297	        matrix,
298	        full_range,
299	    };
300	    Ok(Av1Config {
301	        record: vec![
302	            AV1C_MARKER_VERSION,
303	            (profile << 5) | (level & 0x1f),
304	            flags,
305	            0x00,
306	        ],
307	        seq_profile: profile,
308	        seq_level_idx: level,
309	        seq_tier: tier,
310	        bit_depth: [8, 10, 12][usize::from(high_bitdepth) + usize::from(twelve_bit)],
311	        monochrome,
312	        color,
313	    })
314	}
