 56	/// One OBU's place in a run: where it starts, its header's length (the
 57	/// header byte, the extension byte, the size field), its type and where it
 58	/// ends.
 59	struct Obu {
 60	    start: usize,
 61	    header: usize,
 62	    kind: u8,
 63	    end: usize,
 64	}
 65	
 66	/// The OBU at `start` of `bytes`: `None` when its size field is cut short
 67	/// or its payload runs past the end. One without a size field runs to the
 68	/// end (AV1 §5.3.1).
 69	fn obu_at(bytes: &[u8], start: usize) -> Option<Obu> {
 70	    let first = *bytes.get(start)?;
 71	    let mut header = 1 + usize::from(first & OBU_EXTENSION_BIT != 0);
 72	    if start + header > bytes.len() {
 73	        return None;
 74	    }
 75	    let end = if first & OBU_HAS_SIZE_BIT != 0 {
 76	        let (size, used) = leb128(&bytes[start + header..])?;
 77	        header += used;
 78	        let size = usize::try_from(size).ok()?;
 79	        (start + header).checked_add(size)?
 80	    } else {
 81	        bytes.len()
 82	    };
 83	    if end > bytes.len() {
 84	        return None;
 85	    }
 86	    Some(Obu {
 87	        start,
 88	        header,
 89	        kind: (first >> 3) & 0x0f,
 90	        end,
 91	    })
 92	}
 93	
 94	/// An unsigned leb128, the shortest spelling of `value`.
 95	fn leb128_bytes(mut value: usize) -> Vec<u8> {
 96	    let mut out = Vec::new();
 97	    loop {
 98	        let byte = (value & 0x7f) as u8;
 99	        value >>= 7;
100	        if value == 0 {
101	            out.push(byte);
102	            return out;
103	        }
104	        out.push(byte | 0x80);
105	    }
106	}
107	
108	/// A big-endian bit reader over a sequence header's payload, naming the
109	/// field it was reading when the bytes ran out.
110	struct Bits<'a> {
111	    bytes: &'a [u8],
112	    at: usize,
113	}
114	
115	impl Bits<'_> {
116	    fn f(&mut self, n: u32, field: &str) -> Result<u64, String> {
117	        let mut value = 0u64;
118	        for _ in 0..n {
119	            let Some(byte) = self.bytes.get(self.at / 8) else {
120	                return Err(format!(
121	                    "the sequence header ends at bit {}, inside {field}",
122	                    self.at
123	                ));
124	            };
125	            value = (value << 1) | u64::from((byte >> (7 - self.at % 8)) & 1);
126	            self.at += 1;
127	        }
128	        Ok(value)
129	    }
130	
131	    /// One-bit fields read only to be passed over, named in order.
132	    fn flags(&mut self, fields: &str) -> Result<(), String> {
133	        for field in fields.split(' ') {
134	            self.f(1, field)?;
135	        }
136	        Ok(())
137	    }
138	
139	    fn flag(&mut self, field: &str) -> Result<bool, String> {
140	        Ok(self.f(1, field)? == 1)
141	    }
142	
143	    fn byte(&mut self, n: u32, field: &str) -> Result<u8, String> {
144	        Ok(self.f(n, field)? as u8)
145	    }
146	
147	    /// AV1 §4.10.3: leading zeros, then that many bits; a run of 32 or more
148	    /// zeros is the maximum value, and reading past the end is an error, so
149	    /// a payload of zeros cannot loop.
150	    fn uvlc(&mut self, field: &str) -> Result<(), String> {
151	        let mut zeros = 0u32;
152	        while !self.flag(field)? {
153	            zeros += 1;
154	        }
155	        if zeros < 32 {
156	            self.f(zeros, field)?;
157	        }
158	        Ok(())
159	    }
160	}
