301	        record: vec![
302	            AV1C_MARKER_VERSION,
303	            (profile << 5) | (level & 0x1f),
304	            flags,
305	            0x00,
306	        ],
307	        seq_profile: profile,
308	        seq_level_idx: level,
309	        seq_tier: tier,
310	        bit_depth: [8, 10, 12][usize::from(high_bitdepth) + usize::from(twelve_bit)],
311	        monochrome,
312	        color,
313	    })
314	}
315	
316	/// The `av1C` record for the first sequence header OBU in `obus`, an OBU
317	/// run (AV1-ISOBMFF §2.3.3): its four bytes, then that OBU with a size
318	/// field. `Err` names what is missing.
319	pub fn config_record(obus: &[u8]) -> Result<Av1Config, String> {
320	    let mut at = 0;
321	    let obu = loop {
322	        if at >= obus.len() {
323	            return Err(format!("no sequence header OBU in {} bytes", obus.len()));
324	        }
325	        let obu = obu_at(obus, at).ok_or(format!("the OBU at byte {at} runs past the end"))?;
326	        if obu.kind == OBU_SEQUENCE_HEADER {
327	            break obu;
328	        }
329	        at = obu.end;
330	    };
331	    let payload = &obus[obu.start + obu.header..obu.end];
332	    let mut config = parse_sequence_header(payload)?;
333	    // The OBU as it came, but always with a size field (AV1-ISOBMFF §2.3.4).
334	    let first = obus[obu.start];
335	    config.record.push(first | OBU_HAS_SIZE_BIT);
336	    if first & OBU_EXTENSION_BIT != 0 {
337	        config.record.push(obus[obu.start + 1]);
338	    }
339	    config.record.extend(leb128_bytes(payload.len()));
340	    config.record.extend_from_slice(payload);
341	    Ok(config)
342	}
343	
344	/// Removes every temporal delimiter OBU from `bytes` in place (AV1-ISOBMFF
345	/// §2.4: a sample carries none) and answers the length kept; `None`, with
346	/// the bytes untouched, when they are not a run of whole OBUs.
347	pub fn strip_temporal_delimiters(bytes: &mut [u8]) -> Option<usize> {
348	    let mut kept = Vec::new();
349	    let mut at = 0;
350	    while at < bytes.len() {
351	        let obu = obu_at(bytes, at)?;
352	        if obu.kind != OBU_TEMPORAL_DELIMITER {
353	            kept.push(obu.start..obu.end);
354	        }
355	        at = obu.end;
356	    }
357	    let mut write = 0;
358	    for range in kept {
359	        let len = range.len();
360	        bytes.copy_within(range, write);
361	        write += len;
362	    }
363	    Some(write)
364	}
365	
366	/// Makes the `ftyp` box at the start of `head` carry `av01` among its
367	/// compatible brands (AV1-ISOBMFF §2.1): `Ok(false)` when it already does,
368	/// `Ok(true)` when its first `mp41` was rewritten `av01` in place (no size
369	/// or offset moves), and `Err` naming what is missing, the bytes untouched.
370	pub fn brand_av01(head: &mut [u8]) -> Result<bool, String> {
371	    if head.len() < 16 || &head[4..8] != b"ftyp" {
372	        return Err("no ftyp box at byte 0".to_string());
373	    }
374	    let size = u32::from_be_bytes([head[0], head[1], head[2], head[3]]) as usize;
375	    if size < 16 || size > head.len() {
376	        return Err(format!(
377	            "the ftyp box's size {size} is not inside the {} bytes given",
378	            head.len()
379	        ));
380	    }
381	    let brands = 16..size - (size - 16) % 4;
382	    let compatible = |head: &[u8], brand: &[u8; 4]| {
383	        brands
384	            .clone()
385	            .step_by(4)
386	            .find(|at| &head[*at..*at + 4] == brand)
387	    };
388	    if compatible(head, b"av01").is_some() {
389	        return Ok(false);
390	    }
391	    let at = compatible(head, b"mp41")
392	        .ok_or("the ftyp box has no mp41 brand to rewrite as av01".to_string())?;
393	    head[at..at + 4].copy_from_slice(b"av01");
394	    Ok(true)
395	}

